def solve(x):
    defaults = x.get('defaults', {})
    environment = x.get('environment', {})
    explicit = x.get('explicit', {})

    # Merge defaults with environment
    merged = {**defaults, **environment}

    # Merge merged with explicit
    final = {**merged, **explicit}

    # Remove keys that are None
    final = {key: value for key, value in final.items() if value is not None}

    return final
